const i=(t,$="dd-MM-yyyy")=>{if(!t)return"-";let s=t;typeof t=="string"&&(s=t.replace(/\//g," "));const n=new Date(s);if(isNaN(n.getTime()))return String(t);const e=String(n.getDate()).padStart(2,"0"),y=String(n.getMonth()+1).padStart(2,"0"),r=n.getFullYear(),c=String(r).slice(-2);switch($){case"dd-MM-yyyy":return`${e}-${y}-${r}`;case"MM-dd-yy":return`${y}-${e}-${c}`;case"MM-dd-yyyy":return`${y}-${e}-${r}`;case"yyyy-MM-dd":return`${r}-${y}-${e}`;default:return`${e}-${y}-${r}`}};export{i as f};
